CREATE TEMPORARY VIEW exp_group_data_${grass_region_without_quote} AS
SELECT
/*+REPARTITION(6000, user_id)*/
    user_id
    ,exp_group_id
FROM 
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE 
    local_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND user_id > 0
    and is_assignment_log = 1
    and is_rcmd_search_whitelist = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW order_data_${grass_region_without_quote} AS
SELECT
    user_id
    ,case when platform in ('ios_app', 'android_app') then platform else 'others' end as platform
    ,scenario_tag
    ,local_date
FROM srdi_mart.dws_sr_data_warehouse_platform_user_level_benchmark_1d
WHERE local_date between date_add(${local_date}, -179) and ${local_date}
AND grass_region IN (${grass_region})
AND order_cnt > 0
AND user_id > 0
AND user_id IS NOT NULL
AND feature_detail = '__ALL__'
AND (scenario_tag LIKE 'DA_%'
    OR scenario_tag = '__ALL__')
GROUP BY 1,2,3,4
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW order_data_180d_${grass_region_without_quote} AS
SELECT
    user_id
    ,if(platform IS NULL, '__ALL__', platform) AS platform
    ,scenario_tag

    ,sum(case when local_date between date_add(${local_date}, -29) and ${local_date} then 1 else 0 end)     days_count_30
    ,sum(case when local_date between date_add(${local_date}, -59) and ${local_date} then 1 else 0 end)     days_count_60
    ,sum(case when local_date between date_add(${local_date}, -89) and ${local_date} then 1 else 0 end)     days_count_90
    ,sum(case when local_date between date_add(${local_date}, -179) and ${local_date} then 1 else 0 end)     days_count_180

    ,max(case when local_date between date_add(${local_date}, -29) and ${local_date} then local_date else null end)     max_date_30
    ,max(case when local_date between date_add(${local_date}, -59) and ${local_date} then local_date else null end)     max_date_60
    ,max(case when local_date between date_add(${local_date}, -89) and ${local_date} then local_date else null end)     max_date_90
    ,max(case when local_date between date_add(${local_date}, -179) and ${local_date} then local_date else null end)     max_date_180

    ,min(case when local_date between date_add(${local_date}, -29) and ${local_date} then local_date else null end)     min_date_30
    ,min(case when local_date between date_add(${local_date}, -59) and ${local_date} then local_date else null end)     min_date_60
    ,min(case when local_date between date_add(${local_date}, -89) and ${local_date} then local_date else null end)     min_date_90
    ,min(case when local_date between date_add(${local_date}, -179) and ${local_date} then local_date else null end)     min_date_180
FROM 
    order_data_${grass_region_without_quote}
GROUP BY 
    1,3
    ,CUBE(platform);

--sql_divide_splitter--

CREATE TEMPORARY VIEW order_cube_data_${grass_region_without_quote} AS
SELECT
    user_id
    ,platform
    ,scenario_tag

    ,case when days_count_30 > 1 then (datediff(max_date_30, min_date_30)+0.0)/(days_count_30-1) else null end  as avg_repurchase_days_30
    ,case when days_count_60 > 1 then (datediff(max_date_60, min_date_60)+0.0)/(days_count_60-1) else null end  as avg_repurchase_days_60
    ,case when days_count_90 > 1 then (datediff(max_date_90, min_date_90)+0.0)/(days_count_90-1) else null end  as avg_repurchase_days_90
    ,case when days_count_180 > 1 then (datediff(max_date_180, min_date_180)+0.0)/(days_count_180-1) else null end  as avg_repurchase_days_180
FROM order_data_180d_${grass_region_without_quote};

--sql_divide_splitter--
CREATE TEMPORARY VIEW order_explode_data_${grass_region_without_quote} AS
SELECT
/*+REPARTITION(6000, user_id)*/
    user_id
    ,platform
    ,scenario_tag
    ,day_type
    ,avg_repurchase_days
FROM 
    order_cube_data_${grass_region_without_quote}
    LATERAL VIEW STACK(
        4,
        30,  avg_repurchase_days_30,
        60,  avg_repurchase_days_60,
        90,  avg_repurchase_days_90,
        180, avg_repurchase_days_180
        ) x AS day_type, avg_repurchase_days
WHERE
    avg_repurchase_days IS NOT NULL;

--sql_divide_splitter--

CREATE TEMPORARY VIEW join_table_${grass_region_without_quote} AS
SELECT
    a.exp_group_id
    ,b.platform
    ,b.scenario_tag
    ,day_type
    ,avg_repurchase_days
    ,COUNT(1) AS uu
FROM exp_group_data_${grass_region_without_quote} a
INNER JOIN order_explode_data_${grass_region_without_quote} b 
    ON a.user_id=b.user_id
GROUP BY 
    1,2,3,4,5;

--sql_divide_splitter--

CREATE TEMPORARY VIEW window_table_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,platform
    ,scenario_tag
    ,day_type
    ,avg_repurchase_days
    ,uu
    ,SUM(uu) OVER (PARTITION BY platform,exp_group_id,scenario_tag,day_type ORDER BY avg_repurchase_days) AS cum_uu_cnt
    ,SUM(uu) OVER (PARTITION BY platform,exp_group_id,scenario_tag,day_type)  AS total_uu
FROM 
    join_table_${grass_region_without_quote}
;

--sql_divide_splitter--

CREATE TEMPORARY VIEW percentile_table_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,platform
    ,scenario_tag
    ,day_type

    ,SUM(avg_repurchase_days * uu) / SUM(uu) AS avg_repurchase_days

    ,MIN(CASE WHEN cum_uu_cnt >=  CEIL(0.25 * total_uu) THEN avg_repurchase_days END) AS p25
    ,MIN(CASE WHEN cum_uu_cnt >= CEIL(0.50 * total_uu) THEN avg_repurchase_days END) AS p50
    ,MIN(CASE WHEN cum_uu_cnt >= CEIL(0.75 * total_uu) THEN avg_repurchase_days END) AS p75
    ,MIN(CASE WHEN cum_uu_cnt >= CEIL(0.90 * total_uu) THEN avg_repurchase_days END) AS p90
FROM 
    window_table_${grass_region_without_quote}
GROUP BY 
    1,2,3,4
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_platform_exp_level_repurchase_days_180d
PARTITION (grass_region = ${grass_region}, local_date = ${local_date})
SELECT
/*+REPARTITION(10)*/
    exp_group_id
    ,platform
    ,scenario_tag
    ,MAX(IF(day_type = 30, avg_repurchase_days, NULL)) AS avg_repurchase_days_30
    ,MAX(IF(day_type = 60, avg_repurchase_days, NULL)) AS avg_repurchase_days_60
    ,MAX(IF(day_type = 90, avg_repurchase_days, NULL)) AS avg_repurchase_days_90
    ,MAX(IF(day_type = 180, avg_repurchase_days, NULL)) AS avg_repurchase_days_180

-- 25percentile
    ,MAX(IF(day_type = 30, p25, NULL)) AS `25pct_repurchase_days_30`
    ,MAX(IF(day_type = 60, p25, NULL)) AS `25pct_repurchase_days_60`
    ,MAX(IF(day_type = 90, p25, NULL)) AS `25pct_repurchase_days_90`
    ,MAX(IF(day_type = 180, p25, NULL)) AS `25pct_repurchase_days_180`

-- 50percentile
    ,MAX(IF(day_type = 30, p50, NULL)) AS `50pct_repurchase_days_30`
    ,MAX(IF(day_type = 60, p50, NULL)) AS `50pct_repurchase_days_60`
    ,MAX(IF(day_type = 90, p50, NULL)) AS `50pct_repurchase_days_90`
    ,MAX(IF(day_type = 180, p50, NULL)) AS `50pct_repurchase_days_180`

-- 75percentile
    ,MAX(IF(day_type = 30, p75, NULL)) AS `75pct_repurchase_days_30`
    ,MAX(IF(day_type = 60, p75, NULL)) AS `75pct_repurchase_days_60`
    ,MAX(IF(day_type = 90, p75, NULL)) AS `75pct_repurchase_days_90`
    ,MAX(IF(day_type = 180, p75, NULL)) AS `75pct_repurchase_days_180`

-- 90percentile
    ,MAX(IF(day_type = 30, p90, NULL)) AS `90pct_repurchase_days_30`
    ,MAX(IF(day_type = 60, p90, NULL)) AS `90pct_repurchase_days_60`
    ,MAX(IF(day_type = 90, p90, NULL)) AS `90pct_repurchase_days_90`
    ,MAX(IF(day_type = 180, p90, NULL)) AS `90pct_repurchase_days_180`
FROM 
    percentile_table_${grass_region_without_quote}
GROUP BY 
    1,2,3;
